CREATE PROCEDURE [dbo].[BR_R29_VIB_WB_3] (
      @transaction_id INT,
      @userid INT,
      @rulecode NVARCHAR(20)
)
AS
BEGIN
    DECLARE @Result TABLE (
        Authority NVARCHAR(50),
        CMID INT
    );

    -- Insert data into @Result
    INSERT INTO @Result (Authority, CMID)
    SELECT t1.Authority, t2.CMID
    FROM classification AS t1
    JOIN eligibility_rule AS t2 ON t1.classification_id = t2.constant_matrix_id
    WHERE t1.item = 'transaction'
      AND t1.item_id = @transaction_id
      AND t1.var_name = 'WB_Approval_Matrix'
      AND t1.ddate IS NULL;

    -- Insert data into approval_var_log
    INSERT INTO approval_var_log (item, item_id, var_name, var_value, var_type, iuser, idate)
    SELECT 'transaction', @transaction_id, 'WB_Approval_Matrix',
           Authority, CMID, @userid, GETDATE()
    FROM @Result;

    SELECT * FROM @Result;
END;

